pub fn compare(a: &[u8], b: &[u8]) -> std::cmp::Ordering {
    a.iter()
        .map(|byte| HFS_CHARORDER[*byte as usize])
        .cmp(b.iter().map(|byte| HFS_CHARORDER[*byte as usize]))
}
pub fn encode(name: &str) -> Option<Vec<u8>> {
    let name = match name {
        "．" => ".",
        "．．" => "..",
        name => name,
    };
    name.chars()
        .map(|character| {
            if character == ':' {
                Some(b'/')
            } else if character == '＼' {
                Some(b'\\')
            } else if character.is_ascii() {
                Some(character as u8)
            } else {
                HIGH.iter()
                    .position(|value| *value == character)
                    .map(|index| index as u8 + 128)
            }
        })
        .collect()
}
pub fn display(name: &[u8]) -> String {
    match name {
        b"." => "．".into(),
        b".." => "．．".into(),
        name => decode(name).replace('/', ":").replace('\\', "＼"),
    }
}
